#!/bin/bash
# Test Script v3 - Controlled Testing
# Generated by flowsh v1.0.0 
# Source: Agent Workflow Example

set -euo pipefail

# Workflow variables
declare -A workflow_vars

# Control flags for testing
USE_MOCK_TOOLS=${USE_MOCK_TOOLS:-true}

# Mock opencode command for testing
mock_opencode() {
    echo "🤖 Mock opencode called with prompt:"
    echo "---"
    local prompt="$1"
    echo "${prompt:0:100}..." # Show first 100 chars
    echo "---"
    echo "✅ Mock agent completed task successfully"
    return 0
}

# Mock make command for testing  
mock_make() {
    case "$1" in
        "test")
            echo "🧪 Running tests..."
            sleep 1
            echo "✅ All tests passed"
            return 0
            ;;
        *)
            echo "❌ Unknown make target: $1"
            return 1
            ;;
    esac
}

# Initialize workflow
init_workflow() {
    workflow_vars["task_description"]="${1:-}"
    workflow_vars["project_path"]="${2:-}"
    
    [[ -z "${workflow_vars["task_description"]}" ]] && {
        echo "Error: task_description is required" >&2
        echo "Usage: $0 'task description' /path/to/project" >&2
        exit 1
    }
    [[ -z "${workflow_vars["project_path"]}" ]] && {
        echo "Error: project_path is required" >&2
        echo "Usage: $0 'task description' /path/to/project" >&2
        exit 1
    }
    
    # Validate project path exists
    [[ ! -d "${workflow_vars["project_path"]}" ]] && {
        echo "Error: project_path '${workflow_vars["project_path"]}' does not exist" >&2
        exit 1
    }
    
    echo "✓ Workflow initialized successfully"
    echo "  Task: ${workflow_vars["task_description"]}"
    echo "  Project: ${workflow_vars["project_path"]}"
    echo "  Mock mode: $USE_MOCK_TOOLS"
}

# Execute agent node: code_agent
execute_agent_node_code_agent() {
    echo "🚀 Running Code Agent..."
    
    # Resolve template from registry
    local template_content
    template_content=$(resolve_template "task-planner" "library")
    [[ $? -eq 0 ]] || {
        echo "ERROR: Failed to resolve template" >&2
        exit 1
    }
    
    local prompt
    prompt=$(render_template "$template_content" "${workflow_vars["task_description"]}")
    [[ $? -eq 0 ]] || {
        echo "ERROR: Failed to render template" >&2
        exit 1
    }
    
    # Call agent CLI tool
    local agent_exit_code=0
    if [[ "$USE_MOCK_TOOLS" == "true" ]]; then
        mock_opencode "$prompt" || agent_exit_code=$?
    elif command -v opencode >/dev/null 2>&1; then
        timeout 30 opencode run "$prompt" || agent_exit_code=$?
    else
        echo "📝 opencode not found, falling back to mock"
        mock_opencode "$prompt" || agent_exit_code=$?
    fi
    
    [[ $agent_exit_code -eq 0 ]] || {
        echo "ERROR: Agent execution failed with exit code $agent_exit_code" >&2
        exit 1
    }
    
    echo "✅ Code agent completed successfully"
}

# Execute code node: validate_code
execute_code_node_validate_code() {
    echo "🔍 Running validation..."
    
    # Change to project directory
    local original_dir=$(pwd)
    cd "${workflow_vars["project_path"]}"
    
    # Execute validation command
    local exit_code=0
    if [[ "$USE_MOCK_TOOLS" == "true" ]]; then
        mock_make "test" || exit_code=$?
    elif command -v make >/dev/null 2>&1; then
        make test || exit_code=$?
    else
        echo "📝 make not found, falling back to mock"
        mock_make "test" || exit_code=$?
    fi
    
    # Return to original directory
    cd "$original_dir"
    
    # Handle success/failure routing
    if [[ $exit_code -eq 0 ]]; then
        echo "✅ Validation passed - proceeding to deploy"
        execute_node_deploy
    else
        echo "❌ Validation failed - proceeding to fix issues"
        execute_node_fix_issues
    fi
}

# Deploy node implementation
execute_node_deploy() {
    echo "🚀 Deploying application..."
    echo "   - Building production assets..."
    echo "   - Uploading to server..."
    echo "   - Running health checks..."
    echo "✅ Deployment completed successfully"
}

# Fix issues node implementation
execute_node_fix_issues() {
    echo "🔧 Fixing issues..."
    echo "   - Analyzing test failures..."
    echo "   - Applying automated fixes..."
    echo "   - Running validation again..."
    echo "✅ Issues fixed, ready for re-validation"
}

# Template resolution helper
resolve_template() {
    local template_id="$1"
    local source="$2"
    
    case "$template_id" in
        "task-planner")
            cat <<'TEMPLATE'
You are a task planner. Break down this task: {{task_description}}

Create actionable steps and implement them systematically.
Focus on:
1. Understanding requirements
2. Breaking down into subtasks  
3. Implementation planning
4. Testing strategy
TEMPLATE
            ;;
        *)
            echo "Error: Unknown template '$template_id'" >&2
            return 1
            ;;
    esac
}

# Template rendering helper  
render_template() {
    local template="$1"
    local task_description="$2"
    
    echo "$template" | sed "s|{{task_description}}|$task_description|g"
}

# Main execution
main() {
    init_workflow "$@"
    execute_agent_node_code_agent
    execute_code_node_validate_code
}

# Usage help
show_usage() {
    cat <<EOF
Usage: $0 [OPTIONS] 'task description' /path/to/project

Options:
  --no-mock    Use real tools instead of mocks
  --help       Show this help message

Examples:
  $0 "Implement user auth" /path/to/project
  USE_MOCK_TOOLS=false $0 "Fix bug in API" /path/to/project
EOF
}

# Parse arguments
while [[ $# -gt 0 ]]; do
    case $1 in
        --no-mock)
            USE_MOCK_TOOLS=false
            shift
            ;;
        --help)
            show_usage
            exit 0
            ;;
        -*)
            echo "Unknown option $1" >&2
            show_usage >&2
            exit 1
            ;;
        *)
            break
            ;;
    esac
done

# Run if called directly
if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
fi